await provider
  .given('existe el producto 42')
  .uponReceiving('una petición del producto 42')
  .withRequest({ method: 'GET', path: '/api/productos/42' })
  .willRespondWith({
    status: 200,
    body: { id: 42, nombre: like('Poncho'), precio: decimal(25.0) },
  })
  .executeTest(async (mock) => {
    const p = await new CatalogoApi(mock.url).producto(42);
